#!/usr/bin/env python3
"""Estratti Z80 e dati delle locazioni, con ricomposizione byte per byte."""
import argparse,json,sys
from pathlib import Path
from extract_locations import extract

def main():
    ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('--project',type=Path,default=Path(__file__).resolve().parents[2]);ap.add_argument('--output',type=Path,default=Path(__file__).resolve().parent/'results');a=ap.parse_args()
    sys.path.insert(0,str(a.project/'skoolkit-10.1'))
    from skoolkit.traceutils import disassemble
    from skoolkit.z80 import Assembler
    data=extract(a.project);m=bytes(0x5d80)+(a.project/'sherlock-analisi/block-10.bin').read_bytes();asm=Assembler()
    regions=[(0x840b,0x8b6f,'data'),(0xc00c,0xc03b,'code'),(0xc821,0xc898,'code'),(0xca7f,0xcaae,'code'),(0xd045,0xd05a,'code'),(0xd05a,0xd078,'data'),(0xd078,0xd0dc,'code'),(0xd0dc,0xd0dd,'data'),(0xd0dd,0xd1db,'code'),(0xd224,0xd275,'code'),(0xd33c,0xd349,'code'),(0xd39b,0xd5c9,'code'),(0xd5c9,0xd5d3,'data'),(0xd5d3,0xd6b8,'code'),(0xdc20,0xdc57,'code'),(0xdc57,0xdc5b,'data'),(0xdc5b,0xdc7b,'code'),(0xdc7b,0xdc7d,'data'),(0xdc7d,0xdc8d,'code'),(0xdcd2,0xdcff,'code'),(0xdcff,0xdd03,'data'),(0xdd03,0xdd07,'data'),(0xdd07,0xdd52,'code'),(0xdd52,0xdd65,'data'),(0xdd65,0xdd84,'code')]
    comments={0x840b:'Indice: 106 puntatori alle locazioni, poi slot 6A verso indice entita.',0x84df:'Slot 6A: punta a 8B6F; NON e una locazione.',0xc00c:'Classe temporale per luce e varianti delle descrizioni.',0xc821:'Filtro percettivo: barriere di contenimento, flag visibilita, occorrenze nella stanza.',0xc863:'Trova barriera del contenimento a partire dall ID.',0xc86e:'Risale genitori finche visibili e aperti/rotti; FF se nessuna barriera.',0xca7f:'Dopo il corpo della regola, verifica se Holmes ha cambiato stanza.',0xca9e:'Ingresso: bit6 del record locazione seleziona descrizione breve/estesa.',0xcaa9:'Marca visitata soltanto nel percorso del primo ingresso.',0xd045:'Aggiorna A009 con locazione corrente del giocatore.',0xd05a:'Riferimenti lessicali alle relazioni; da D064 anche direzioni. Non Z80.',0xd078:'Test del buio: contesto, flag stanza, fascia oraria e sorgenti di luce percepibili.',0xd0dc:'Stato mutabile: forma di descrizione (es. LOOK THROUGH).',0xd0dd:'Seleziona frase generica e relazione locativa dai bit1..3 del record.',0xd102:'Descrizione estesa della scena.',0xd113:'Grafica opzionale, eventuale contenitore del giocatore, testo, uscite, oggetti.',0xd16b:'Puntatore descrizione compressa a +7/+8.',0xd182:'Puntatore zero: frase generica e nome; altrimenti A59F.',0xd1b2:'Descrizione breve: nome; poi uscite senza oggetto e oggetti, oppure buio.',0xd1c6:'Stampa nome locazione, campi +1/+3/+5.',0xd224:'ID locazione -> IX tramite indice 840B.',0xd237:'ID entita -> IX tramite indice 8B6F.',0xd249:'Propaga la locazione a tutti i discendenti dell entita spostata.',0xd33c:'Record della stanza corrente dell attore.',0xd39b:'Matching nominale delle locazioni; esclude slot 6A.',0xd448:'Cerca uscita per codice direzione; triplette a record+9.',0xd46c:'Cerca uscita per ID del passaggio, campo+1.',0xd471:'Cerca uscita per destinazione, campo+2; modifica operando D48D.',0xd495:'Locazione singola di un entita; FF se non ha esattamente un occorrenza.',0xd4a7:'You can see...: elenco dei figli diretti di FF.',0xd4cc:'Conta candidati per un dato genitore.',0xd4ef:'Filtro elenco: genitore, non attore, C821, meno di2 occorrenze, non posseduto.',0xd51a:'Stampa elenco e ricorsione sui contenuti.',0xd531:'Marca bit7 di +6 dell entita elencata.',0xd55a:'Secondo passaggio: presenta ricorsivamente i contenuti.',0xd590:'Contenitore personale: carrying; altrimenti relazione in/on/behind/under/tied.',0xd5c9:'Cinque riferimenti lessicali delle relazioni di contenimento.',0xd5d3:'Relazione dal campo+4 &7 del contenitore.',0xd5ef:'Prepara iterazione delle triplette di uscita.',0xd60b:'Descrive passaggi nonzero con flag visibilita: To the west..., Above..., Below...',0xd671:'Itera uscite direzionali senza entita interposta.',0xd68c:'Elenco generico delle uscite senza passaggio.',0xdc20:'LOOK THROUGH: trasferimento temporaneo, descrizione breve, ripristino posizione.',0xdc4e:'Predicato GO THROUGH: cerca passaggio poi condizioni comuni di movimento.',0xdc57:'Header GO THROUGH: 4B 20 4E DC; costo2, predicato DC4E.',0xdc5b:'Ricava direzione dall arco e usa corpo comune DD07.',0xdc7b:'Header LOOK: 20 10; richiede luce, costo1.',0xdc7d:'LOOK esplicito richiede sempre D102; qui non marca il bit di visita.',0xdcd2:'Predicato direzioni: uscita, vincoli contesto, attore non contenuto, destinazione nonzero, passaggio.',0xdcff:'Puntatore ultima destinazione (word) e ID destinazione DD01. Stato, non Z80.',0xdd03:'Header movimento direzionale: 60 20 D2 DC; luce, costo2, predicato DCD2.',0xdd07:'Destinazione dalla tripletta poi DD0B.',0xdd0b:'Sposta attore: aggiorna campo+0F e discendenti D249.',0xdd35:'Passaggio 0 libero; altrimenti flag aperto/rotto e confronto campo+2 con quello dell attore.',0xdd52:'Header GO INTO e sequenza differita; poi header regola ausiliaria DD61. NON Z80.',0xdd65:'Salva direzione trovata nel primo argomento della sequenza.',0xdd6e:'Cerca locazione adiacente per argomento e verifica direzione inferiore a0B.'}
    for r in data['rooms']:
        p=int(r['record'],16);comments[p]=f"Locazione {r['id']:03d}: {r['name_hint'] or 'slot nullo'}. Flags; nome+qualificatori; descrizione; triplette; FF."
        for e in r['exits']:comments[int(e['address'],16)]=f"Uscita {e['direction']}: passaggio {e['gate']}, destinazione {e['target']}."
    lines=['; Sherlock - locazioni. Dati e bytecode separati da codice Z80.'];count=total=0
    for start,end,kind in regions:
        lines+=['',f'    ORG ${start:04X}',f'; {kind.upper()} fino a ${end-1:04X}'];p=start
        while p<end:
            if p in comments:lines.append('; '+comments[p])
            if kind=='code':op,n=disassemble(m,p);count+=1
            else:
                n=min([p+8,end]+[q for q in comments if p<q<min(p+8,end)])-p;op='DEFB '+','.join(f'${v:02X}' for v in m[p:p+n])
            assert p+n<=end,(hex(p),op);assert bytes(asm.assemble(op,p))==m[p:p+n],hex(p)
            lines.append(f'    {op:<33} ; ${p:04X} {m[p:p+n].hex(" ")}');p+=n;total+=n
    a.output.mkdir(parents=True,exist_ok=True);(a.output/'locations.asm').write_text('\n'.join(lines)+'\n')
    report={'instructions':count,'bytes_roundtripped':total,'regions':[{'start':f'{s:04X}','end_exclusive':f'{e:04X}','kind':k} for s,e,k in regions]};(a.output/'listing-verification.json').write_text(json.dumps(report,indent=2)+'\n');print(count,'istruzioni;',total,'byte ricomposti')
if __name__=='__main__':main()
